DELIMITER $$
--
-- Procedimientos
--
CREATE DEFINER=`u469305563_glamcity_db`@`127.0.0.1` PROCEDURE `CleanOfflineUsers` ()   BEGIN
    DECLARE timeout_seconds INT DEFAULT 300;
    
    -- Obtener timeout de configuración
    SELECT config_value INTO timeout_seconds 
    FROM chat_config 
    WHERE config_key = 'online_timeout' 
    LIMIT 1;
    
    -- Marcar usuarios como offline si no han tenido actividad
    UPDATE chat_online_users 
    SET is_online = FALSE 
    WHERE last_activity < DATE_SUB(NOW(), INTERVAL timeout_seconds SECOND)
    AND is_online = TRUE;
    
    -- Eliminar registros muy antiguos (más de 24 horas)
    DELETE FROM chat_online_users 
    WHERE last_activity < DATE_SUB(NOW(), INTERVAL 24 HOUR)
    AND is_online = FALSE;
END$$

--
-- Funciones
--
CREATE DEFINER=`u469305563_glamcity_db`@`127.0.0.1` FUNCTION `GetOnlineUsersCount` () RETURNS INT(11) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE user_count INT DEFAULT 0;
    
    -- Limpiar usuarios offline primero
    CALL CleanOfflineUsers();
    
    -- Contar usuarios online
    SELECT COUNT(*) INTO user_count
    FROM chat_online_users
    WHERE is_online = TRUE;
    
    RETURN user_count;
END$$

DELIMITER ;

