-- Estructura de tabla para la tabla `pedidos`
--

CREATE TABLE `pedidos` (
  `id` int(11) NOT NULL,
  `numero_guia` varchar(20) NOT NULL,
  `nombre_cliente` varchar(255) NOT NULL,
  `correo_cliente` varchar(255) NOT NULL,
  `numero_cliente` varchar(20) NOT NULL,
  `notas` text DEFAULT NULL,
  `prioridad` varchar(20) NOT NULL DEFAULT 'normal',
  `archivo_adjunto` varchar(255) DEFAULT NULL,
  `area_id` int(11) DEFAULT 1,
  `estado_id` int(11) DEFAULT 1,
  `creado_por` int(11) NOT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `prioridad_rank` tinyint(4) GENERATED ALWAYS AS (case when `prioridad` = _utf8mb4'alta' then 0 when `prioridad` = _utf8mb4'normal' then 1 else 2 end) STORED
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

