--
-- Estructura de tabla para la tabla `pedidos_eliminados`
--

CREATE TABLE `pedidos_eliminados` (
  `id` int(11) NOT NULL,
  `pedido_id` int(11) NOT NULL,
  `numero_guia` varchar(255) DEFAULT NULL,
  `nombre_cliente` varchar(255) DEFAULT NULL,
  `numero_cliente` varchar(50) DEFAULT NULL,
  `usuario_id` int(11) DEFAULT NULL,
  `fecha_eliminacion` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

