DELIMITER $$
--
-- Eventos
--
CREATE DEFINER=`u469305563_glamcity_db`@`127.0.0.1` EVENT `CleanOldChatData` ON SCHEDULE EVERY 1 DAY STARTS '2025-09-16 19:49:51' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Limpiar usuarios offline
    CALL CleanOfflineUsers();
    
    -- Opcional: Eliminar mensajes muy antiguos (más de 30 días)
    -- DELETE FROM chat_messages WHERE created_at < DATE_SUB(NOW(), INTERVAL 30 DAY);
END$$

DELIMITER ;
